/* Generated by tools/build.js from data/security-plus.js. Edit that file, not this one. */
CertHub.addQuestions("security-plus", [["s1",1,1,"A company installs a mantrap at its data center entrance. Which category and type of control is this?",["Technical, detective","Physical, preventive","Managerial, corrective","Operational, compensating"],1,"A mantrap physically stops tailgating before it happens, so it is a physical, preventive control.",""],["s2",1,1,"After a break-in, the security team reviews recorded camera footage to identify the intruder. The cameras are acting as which control type?",["Preventive","Corrective","Detective","Directive"],2,"Reviewing footage after the fact identifies what happened, which is detective.",""],["s3",1,1,"Which technology primarily provides non-repudiation?",["Symmetric encryption","Digital signatures","Hashing alone","Access control lists"],1,"A digital signature is made with the sender's private key, so the sender can't credibly deny signing.",""],["s4",1,1,"In a zero trust architecture, which component decides whether a subject is granted access to a resource?",["Policy enforcement point","Policy engine","Implicit trust zone","Data plane"],1,"The policy engine (in the control plane) makes the decision; the enforcement point applies it.",""],["s5",1,1,"A team deploys a fake SSH server that logs every attacker command and blocks the source IP afterward. What is the fake server?",["IDS sensor","Honeypot","Jump server","DMZ host"],1,"A decoy system designed to attract and record attackers is a honeypot, a deception technology.","Securing Servers Using Honeypots and IP Blocking"],["s6",1,1,"A DDoS attack against the company website primarily impacts which part of the CIA triad?",["Confidentiality","Integrity","Availability","Non-repudiation"],2,"DDoS prevents legitimate users from reaching the service, an availability impact.",""],["s7",2,1,"What is the main purpose of hashing in data security?",["To encrypt data for secure transmission","To verify data integrity by detecting unauthorized changes","To compress data","To store passwords so they can be recovered"],1,"Hashing is one-way and used for integrity: any change to the input changes the hash.","Unit 3 Assessment Review (missed)"],["s8",2,1,"Adding unique random data to each password before hashing mainly defends against:",["Keyloggers","Rainbow table attacks","Phishing","Replay attacks"],1,"That random data is a salt; it makes precomputed rainbow tables useless.",""],["s9",2,1,"Which of these is a symmetric encryption algorithm?",["RSA","ECC","AES","Diffie-Hellman"],2,"AES uses one shared key. RSA and ECC are asymmetric; Diffie-Hellman is key exchange.",""],["s10",2,1,"Which technique makes a weak password harder to crack by running it through many hashing rounds?",["Key stretching (e.g. PBKDF2, bcrypt)","Steganography","Tokenization","Key escrow"],0,"Key stretching repeats hashing to slow down brute force.",""],["s11",2,1,"A change fails during the maintenance window. Which document tells the admin how to return to the previous state?",["Impact analysis","Backout plan","Standard operating procedure","Change request"],1,"The backout plan describes how to undo the change.",""],["s12",2,1,"Which group reviews and approves changes before they are implemented?",["Incident response team","Change advisory board","Red team","Data owners"],1,"The CAB evaluates risk and approves or rejects change requests.",""],["s13",3,1,"A company needs one certificate for example.com, example.net and shop.example.org. Which certificate fits?",["Wildcard certificate","Self-signed certificate","SAN certificate","Code-signing certificate"],2,"Subject Alternative Names list multiple distinct domains. A wildcard only covers one domain's first-level subdomains.",""],["s14",3,1,"Which method checks a certificate's revocation status in real time without downloading the full list?",["CRL","OCSP","CSR","Key escrow"],1,"OCSP queries the CA's responder for one certificate's status.",""],["s15",3,1,"Which best describes how a digital signature is created?",["Encrypt the whole message with the recipient's public key","Hash the message and encrypt the hash with the sender's private key","Hash the message and encrypt the hash with the recipient's public key","Encrypt the message with a shared symmetric key"],1,"Signing uses the sender's private key on the hash; anyone can verify with the sender's public key.","Block 08 Review"],["s16",3,1,"A certificate signing request (CSR) contains the requester's:",["Private key","Public key","Root certificate","CRL"],1,"The CSR carries the public key and identity info; the private key never leaves the requester.",""],["s17",3,1,"A data center needs a tamper-resistant appliance to generate and store keys for many servers. What should it deploy?",["TPM","HSM","Secure enclave","Key escrow"],1,"An HSM manages keys at scale; a TPM protects keys for a single device.",""],["s18",4,4,"An admin needs to replace Telnet on network devices. Which protocol and port should be used?",["SSH, 22","SNMP, 161","HTTPS, 443","FTP, 21"],0,"SSH on TCP 22 is the encrypted replacement for Telnet.","Block 07 Review"],["s19",4,4,"Which port does LDAP over TLS (LDAPS) use by default?",["389","443","636","3389"],2,"LDAPS uses 636; plain LDAP uses 389.",""],["s20",4,2,"An attacker sends forged replies so hosts map the gateway's IP to the attacker's MAC. What attack is this?",["DNS poisoning","ARP poisoning","MAC flooding","VLAN hopping"],1,"ARP maps IP to MAC; forging those replies creates an on-path position.","Block 06 Review"],["s21",4,3,"What does DNSSEC add to DNS?",["Encryption of queries","Integrity and origin authentication of DNS responses","Load balancing","Faster resolution"],1,"DNSSEC signs records so resolvers can verify they weren't tampered with. It doesn't encrypt.",""],["s22",4,4,"A firewall log shows repeated inbound connections to TCP 3389. Which service is being targeted?",["SMB","SSH","RDP","SQL Server"],2,"TCP 3389 is Remote Desktop Protocol.",""],["s23",5,2,"A group that is well-funded, highly sophisticated and conducts long-term espionage against telecom companies is most likely a:",["Hacktivist","Nation-state actor","Unskilled attacker","Insider threat"],1,"Resources, sophistication and espionage goals point to a nation-state APT, like Salt Typhoon.","Warm Ups (Salt Typhoon)"],["s24",5,2,"What most often motivates a hacktivist?",["Financial gain","Philosophical or political beliefs","Espionage for a government","Revenge against an employer"],1,"Hacktivists act on ideology or causes.","Common Types of Threat Actors"],["s25",5,2,"An employee stores company files in a personal cloud account the IT department never approved. This is:",["Shadow IT","Insider sabotage","Data exfiltration by a nation-state","A watering hole"],0,"Using unapproved tech outside IT's control is shadow IT.",""],["s26",5,2,"A user receives a text message with a link claiming their bank account is locked. This is:",["Vishing","Smishing","Whaling","Pharming"],1,"Phishing via SMS is smishing; via voice is vishing.",""],["s27",5,2,"Attackers compromise a news site that a target company's engineers visit daily. What attack is this?",["Typosquatting","Watering hole","Pretexting","Brand impersonation"],1,"Infecting a site the target group already trusts and visits is a watering hole attack.",""],["s28",5,2,"A caller claims to be from IT support and invents a story about a failed update to get a user's password. This is:",["Pretexting","Tailgating","Credential stuffing","Spear phishing"],0,"Building a false scenario to gain trust is pretexting.",""],["s29",6,2,"Unauthorized users can view customer records because of weak permission checks. Which OWASP category applies?",["Security misconfiguration","Broken access control","Injection","Insecure design"],1,"When users can reach data or functions they shouldn't, it's broken access control.","Unit 3 Assessment Review (missed)"],["s30",6,2,"A program checks a file's permissions, then an attacker swaps the file before the program uses it. This is a:",["Buffer overflow","Race condition (TOCTOU)","Memory leak","Integer overflow"],1,"Time-of-check to time-of-use is a race condition.",""],["s31",6,2,"A buffer overflow lets an attacker run code that grants administrative control. Which impact is this?",["Data manipulation","Privilege escalation","System overload","Encryption bypass"],1,"Gaining admin/root from lower access is privilege escalation.","Unit 4 Assessment"],["s32",6,2,"What is the most effective defense against SQL injection?",["Input length limits only","Parameterized queries","Disabling HTTPS","Client-side JavaScript validation"],1,"Prepared statements keep input from being executed as SQL.","Application Vulnerabilities"],["s33",6,2,"A malicious script saved in a product review runs in every visitor's browser. What is this?",["Reflected XSS","Stored XSS","CSRF","SSRF"],1,"Script stored on the server and served to all visitors is stored (persistent) XSS.","Web App Security"],["s34",6,2,"Before release, developers analyze how attackers might exploit an application and prioritize fixes. What process is this?",["Risk transfer analysis","Incident response","Threat modeling","Penetration testing"],2,"Proactively mapping attack paths and prioritizing mitigations is threat modeling.","Unit 3 Assessment Review (missed)"],["s35",6,2,"An attacker crafts a URL that makes the server request http://localhost/admin. What vulnerability is this?",["CSRF","SSRF","Directory traversal","SQL injection"],1,"The server is tricked into making requests to internal resources: server-side request forgery.","Unit 3 Assessment Review"],["s36",7,2,"Malware spreads across the network on its own without any user action. What is it?",["Trojan","Worm","Logic bomb","Spyware"],1,"Worms self-replicate across networks; trojans need a user to run them.","Introduction to Malware"],["s37",7,2,"Code planted by a developer deletes the payroll database if their name is removed from HR records. This is a:",["Rootkit","Logic bomb","Keylogger","RAT"],1,"Malicious code triggered by a condition or date is a logic bomb.",""],["s38",7,2,"Logs show one failed login each on 400 different accounts using the password Winter2026!. What attack is this?",["Brute force","Password spraying","Credential stuffing","Pass the hash"],1,"A few common passwords across many accounts avoids lockouts: password spraying.",""],["s39",7,2,"A user logs in from Dallas and, 10 minutes later, from Moscow. Which indicator is this?",["Resource consumption","Impossible travel","Account lockout","Out-of-cycle logging"],1,"Logins from locations too far apart for the time elapsed indicate impossible travel.",""],["s40",7,2,"An attacker forces a client and server to negotiate an older, weaker version of TLS. This is a:",["Birthday attack","Downgrade attack","Replay attack","Collision attack"],1,"Forcing weaker protocols or ciphers is a downgrade attack.",""],["s41",7,2,"Which malware is most likely to hide its presence by modifying the operating system kernel?",["Adware","Rootkit","Worm","Ransomware"],1,"Rootkits hide at a low level, often the kernel.","Malware Analysis Techniques & Tools"],["s42",8,2,"Which mitigation best limits an attacker's lateral movement after one workstation is compromised?",["Stronger passwords","Network segmentation","Full disk encryption","Security awareness training"],1,"Segmentation contains the attacker to one zone.",""],["s43",8,2,"Which control allows only pre-approved executables to run on a kiosk?",["Block list","Application allow list","Sandboxing","Host-based firewall"],1,"Allow listing blocks everything not explicitly approved.",""],["s44",8,2,"A medical device can't be patched because the vendor no longer supports it. What is the best approach?",["Accept the risk and do nothing","Isolate it on its own segment as a compensating control","Replace its OS yourself","Disable its logging"],1,"Isolation is a compensating control when patching isn't possible.",""],["s45",8,2,"Disabling unused ports and services and changing default passwords are examples of:",["Hardening","Decommissioning","Tokenization","Threat hunting"],0,"Reducing attack surface on a system is hardening.",""],["s46",8,2,"Giving users only the access needed for their job is the principle of:",["Separation of duties","Least privilege","Implicit trust","Job rotation"],1,"Least privilege minimizes damage from compromised or careless accounts.",""],["s47",9,3,"In an IaaS deployment, who is responsible for patching the guest operating system?",["Cloud provider","Customer","Hypervisor vendor","Internet service provider"],1,"In IaaS the provider secures the hardware and hypervisor; the customer secures the OS and above.",""],["s48",9,3,"An attacker breaks out of a virtual machine to access the hypervisor. This is:",["VM sprawl","VM escape","Container drift","Snapshot rollback"],1,"Escaping a guest into the host is VM escape.","Computer Fundamentals (VMs)"],["s49",9,3,"What is a key security benefit of Infrastructure as Code?",["Removes the need for patching","Consistent, repeatable deployments that reduce misconfiguration","Encrypts all traffic automatically","Eliminates the shared responsibility model"],1,"Templates deploy the same reviewed config every time.",""],["s50",9,3,"Why are ICS/SCADA networks often air-gapped or heavily segmented?",["They require high bandwidth","Availability is critical and they often can't be patched quickly","They only use wireless","They are cloud-native"],1,"Industrial systems prioritize availability and often run legacy software.",""],["s51",9,3,"A team restores a lab VM to its state before a malware test. Which feature did they use?",["Snapshot","Container image","Clustering","Load balancing"],0,"Snapshots allow rollback to a previous state.","Computer Fundamentals (VMs)"],["s52",10,3,"Which device sits inline and can actively block malicious traffic?",["IDS","IPS","SIEM","Network tap"],1,"An IPS is inline and can drop traffic; an IDS only alerts.",""],["s53",10,3,"Port-based network access control that authenticates devices through a RADIUS server before granting access is:",["802.11","802.3","802.1X","802.15"],2,"802.1X uses supplicant, authenticator and authentication server.","Block 05 Review"],["s54",10,3,"A firewall fails and blocks all traffic until it's repaired. This is:",["Fail-open","Fail-closed","Active-active","Load balanced"],1,"Fail-closed favors security over availability.",""],["s55",10,3,"Which device is designed to protect web applications from SQL injection and XSS at layer 7?",["Packet filter","WAF","Proxy ARP","VPN concentrator"],1,"A web application firewall inspects HTTP traffic for application attacks.",""],["s56",10,3,"Admins must connect to servers in a secure zone through one hardened, monitored host. That host is a:",["Jump server","Honeypot","Reverse proxy","Load balancer"],0,"A jump server (bastion host) is the controlled entry point.",""],["s57",10,3,"Which approach combines SD-WAN with cloud-delivered security services like CASB and zero trust access?",["NAC","SASE","UTM","SCADA"],1,"Secure Access Service Edge merges networking and security in the cloud.",""],["s58",11,3,"A payment system replaces card numbers with random values mapped to the real numbers in a secure vault. This is:",["Masking","Tokenization","Hashing","Steganography"],1,"Tokenization swaps data for tokens retrievable only through the vault.",""],["s59",11,3,"Data being processed in a server's RAM is in which state?",["At rest","In transit","In use","Archived"],2,"Data actively being processed is in use.",""],["s60",11,3,"Which backup strategy requires only the last full backup and one other set to restore?",["Full + incremental","Full + differential","Incremental only","Snapshot only"],1,"A differential contains all changes since the last full.",""],["s61",11,3,"Which recovery site can take over operations almost immediately?",["Cold site","Warm site","Hot site","Mobile site"],2,"Hot sites are fully equipped with current data.",""],["s62",11,3,"The maximum amount of data an organization can afford to lose, measured in time, is the:",["RTO","RPO","MTTR","MTBF"],1,"Recovery point objective defines acceptable data loss.",""],["s63",11,3,"A web server is overwhelmed by a DDoS. Which component should be scaled first to absorb and distribute traffic?",["Database server","Load balancer","Application code","Backup server"],1,"The load balancer sits in front and distributes incoming traffic.","Unit 4 Assessment"],["s64",12,4,"Which WPA3 feature replaces the pre-shared key handshake to resist offline dictionary attacks?",["TKIP","SAE","WEP","WPS"],1,"Simultaneous Authentication of Equals protects the handshake.",""],["s65",12,4,"Threat information shows a vulnerability's impact depends heavily on your system configuration. Which CVSS score do you adjust?",["Base","Temporal","Environmental","Exploitability"],2,"The environmental score tailors severity to your environment.","Unit 2 Assessment"],["s66",12,4,"A scanner reports a vulnerability that doesn't actually exist on the system. This is a:",["True positive","False positive","False negative","True negative"],1,"Reported but not real is a false positive.",""],["s67",12,4,"Why run a credentialed vulnerability scan?",["It's faster and quieter","It sees installed software and configs, giving more accurate results","It doesn't require permission","It exploits vulnerabilities automatically"],1,"Logging in reveals details an external scan can't see.",""],["s68",12,4,"A pen tester researches a company using WHOIS, job postings and LinkedIn without touching its systems. This is:",["Active reconnaissance","Passive reconnaissance","Vulnerability scanning","Pivoting"],1,"No direct interaction with the target means passive recon (OSINT).","Ethical Hacking & Reconnaissance"],["s69",12,4,"Which nmap scan sends SYN packets and never completes the TCP handshake?",["-sT","-sS","-sU","-sV"],1,"-sS is the half-open SYN scan; -sT completes the connect.","Scanning & Enumeration"],["s70",12,4,"The company buys phones and lets employees use them for personal apps too. Which deployment model is this?",["BYOD","COPE","CYOD","VDI"],1,"Corporate-owned, personally enabled.",""],["s71",13,4,"What does a SIEM do beyond collecting logs?",["Encrypts endpoints","Correlates events across sources and alerts","Blocks malware on hosts","Replaces the firewall"],1,"Correlation and alerting across many log sources is the SIEM's core value.","Logs in Security Information and Event Management"],["s72",13,4,"After setting up logging mechanisms, what is the next stage of the monitoring process?",["Implement alerts","Identify objectives","Use centralized logging","Real-time monitoring"],2,"Objectives → logging → centralize → monitor → alert.","Unit 3 Assessment Review"],["s73",13,4,"Which email control tells receiving servers what to do when SPF or DKIM checks fail?",["DMARC","S/MIME","TLS","DNSSEC"],0,"DMARC publishes the policy and enables reporting.",""],["s74",13,4,"A fitness app gets permission to read your calendar without learning your password. Which protocol enables this?",["SAML","OAuth","LDAP","Kerberos"],1,"OAuth is delegated authorization.","Identity and Access Management"],["s75",13,4,"Admins get elevated rights only for the approved window they need them. This is:",["Just-in-time access (PAM)","Role-based access","Mandatory access control","Federation"],0,"JIT privileged access reduces standing admin rights.",""],["s76",13,4,"A fingerprint scan is which authentication factor?",["Something you know","Something you have","Something you are","Somewhere you are"],2,"Biometrics are something you are.",""],["s77",13,4,"Which tool monitors endpoints for suspicious behavior and can isolate a host automatically?",["DLP","EDR","NAC","WAF"],1,"Endpoint detection and response watches host behavior and responds.",""],["s78",14,4,"An analyst has isolated an infected host from the network. What is the next IR phase?",["Detection","Eradication","Lessons learned","Preparation"],1,"After containment comes eradication (remove the threat), then recovery.","Incident Response & Malware Protection"],["s79",14,4,"Which should be collected first in a forensic investigation?",["Hard disk image","RAM contents","Backup tapes","Printed logs"],1,"Order of volatility: memory disappears first.",""],["s80",14,4,"Documentation of everyone who handled evidence and when is the:",["Legal hold","Chain of custody","E-discovery request","Incident report"],1,"Chain of custody preserves evidence integrity.",""],["s81",14,4,"Legal counsel instructs IT to preserve all email related to a lawsuit. This is a:",["Legal hold","Right to audit","Data retention policy","Chain of custody"],0,"A legal hold suspends normal deletion.",""],["s82",14,4,"Which technology runs automated playbooks to respond to alerts across tools?",["SIEM","SOAR","IDS","DLP"],1,"Security orchestration, automation and response executes playbooks.","SIEM Workflows"],["s83",14,4,"Leaders walk through a ransomware scenario in a conference room without touching systems. This is a:",["Penetration test","Tabletop exercise","Failover test","Red team engagement"],1,"Discussion-based walkthroughs are tabletop exercises.",""],["s84",15,5,"A company buys cyber insurance to cover breach costs. Which risk treatment is this?",["Accept","Avoid","Transfer","Mitigate"],2,"Shifting financial impact to a third party is transfer.",""],["s85",15,5,"An asset is worth $200,000, the exposure factor is 25% and the ARO is 0.5. What is the ALE?",["$25,000","$50,000","$100,000","$12,500"],0,"SLE = 200,000 × 0.25 = 50,000; ALE = 50,000 × 0.5 = 25,000.","Risk Assessment"],["s86",15,5,"Which agreement defines a vendor's guaranteed uptime and response times?",["NDA","SLA","MOU","BPA"],1,"A service level agreement sets measurable performance targets.",""],["s87",15,5,"Under GDPR, the organization that decides why and how personal data is processed is the:",["Data processor","Data controller","Data custodian","Data subject"],1,"The controller determines purpose and means; the processor acts on its behalf.",""],["s88",15,5,"A document with step-by-step instructions for resetting a user's MFA is a:",["Policy","Standard","Procedure","Guideline"],2,"Procedures are step-by-step.",""],["s89",15,5,"Where are identified risks, owners, likelihood and treatment tracked?",["Risk register","Asset inventory","SLA","Change log"],0,"The risk register is the central tracking document.","Risk Assessment"],["s90",15,5,"What is the essential first step in securing an organization's IT assets?",["Deploy antivirus everywhere","Identify and catalog all physical and digital assets","Install firewalls","Train employees"],1,"You can't protect what you don't know you have.","Unit 2 Assessment"],["s91",15,5,"The security team sends fake phishing emails and tracks who clicks. This is part of:",["Penetration testing","Security awareness training","Threat hunting","Vulnerability scanning"],1,"Phishing simulations measure and improve user awareness.",""],["s92",15,5,"Which risk treatment is being used when a company stops offering a product line because its security risk is too high?",["Transfer","Accept","Mitigate","Avoid"],3,"Ending the risky activity entirely is risk avoidance.","Objective 5.2"],["s93",15,5,"The level of risk an organization is willing to pursue to meet its goals is its:",["Risk appetite","Risk register","Residual risk","Inherent risk"],0,"Risk appetite is how much risk leadership will accept in pursuit of objectives; tolerance is the acceptable variation around it.","Objective 5.2"],["s94",15,5,"After new controls are applied, the risk that still remains is called:",["Inherent risk","Residual risk","Control risk","Risk appetite"],1,"Residual risk is what's left after controls; inherent risk is the level before any controls.","Objective 5.2"],["s95",15,5,"A company wants the right to inspect a cloud vendor's security controls. Which contract clause provides this?",["Non-disclosure clause","Right-to-audit clause","Indemnification clause","Service level clause"],1,"A right-to-audit clause lets the customer assess or review the vendor's controls.","Objective 5.3"],["s96",15,5,"Which agreement typically sets the overall terms for future work, with details added later in statements of work?",["MOU","NDA","MSA","SLA"],2,"A master service agreement sets general terms; each SOW defines a specific project under it.","Objective 5.3"],["s97",15,5,"An auditor independent of the company assesses its controls for a report shared with customers. What kind of assessment is this?",["Internal self-assessment","External (third-party) audit","Tabletop exercise","Vulnerability scan"],1,"An independent outside party performing the review is an external audit.","Objective 5.5"],["s98",15,5,"Which document states who is allowed to use company systems and what they may not do with them?",["Acceptable use policy","Incident response plan","Change management procedure","Data retention standard"],0,"The AUP defines permitted and prohibited use of organizational systems.","Objective 5.1"],["s99",15,5,"A business impact analysis identifies that payroll must be restored within 8 hours. This value is the:",["RPO","MTBF","RTO","ARO"],2,"Recovery time objective is the maximum acceptable time to restore a function.","Objective 5.2"],["s100",15,5,"A penetration tester is told nothing about the target environment in advance. What type of test is this?",["Known environment","Partially known environment","Unknown environment","Integrated test"],2,"An unknown-environment (black box) test starts with no prior information.","Objective 5.5"],["s101",15,5,"Failing to meet which obligation is most likely to result in fines and sanctions from a regulator?",["Internal style guidelines","Compliance with applicable laws and regulations","An optional industry white paper","A vendor's marketing claims"],1,"Non-compliance with legal or regulatory requirements carries fines, sanctions and reputational damage.","Objective 5.4"]]);
